class Patient {
    id: string;
    age: int;
    gender: string;
}

let p := new Patient {
    id     := "PAT001",
    age    := 55,
    gender := "M",
};
println(p.id);
println(p.age);

class Greeter {
    prefix: string;

    func say(self, name) {
        println(self.prefix + ", " + name + "!");
    }
}

let g := new Greeter {
    prefix := "Hello",
};
g.say("world");

class Rectangle {
    width: real;
    height: real;

    func area(self) {
        return self.width * self.height;
    }
}

let rect := new Rectangle {
    width  := 5.0,
    height := 3.0,
};
let a := rect.area();
println(a);

let names := ["Alice", "Bob", "Carol"];
for (let i := 0; i < 3; i := i + 1) {
    println(names[i]);
}

class VitalSigns {
    blood_pressure: int;
    heart_rate: int;
}

class LabResults {
    total_cholesterol: int;
}

class Patient {
    patient_id: string;
    age: int;
    gender: string;
    vital_signs: VitalSigns;
    lab_results: LabResults;
}

let vitals := new VitalSigns {
    blood_pressure := 120,
    heart_rate     := 72,
};

let labs := new LabResults {
    total_cholesterol := 190,
};

let patient := new Patient {
    patient_id  := "PAT010",
    age         := 40,
    gender      := "F",
    vital_signs := vitals,
    lab_results := labs,
};

println(patient.patient_id);
println(patient.age);
